steps.script:
var u = GameState.get_unit("U_BEAST_SNAGGA_BOYZ_A")
for m in u.models:
	m["position"] = {"x": float(m.position.x), "y": float(m.position.y) + 120.0}
u.flags["ork11e_riled_up"] = true
var ph = PhaseManager.get_current_phase_instance()
ph.game_state_snapshot = GameState.create_snapshot()
ph._compute_engagement_flags()
tree.root.get_node("Main")._recreate_unit_visuals()
return RulesEngine.is_unit_engaged("U_BEAST_SNAGGA_BOYZ_A", GameState.state)

var info = PhaseManager.get_current_phase_instance().ork11e_reactive_move_info()
var RM = ResourceLoader.load("res://scripts/rules/ReactiveMove11e.gd")
var d := INF
for m in GameState.get_unit("U_BEAST_SNAGGA_BOYZ_A").models:
	if m.get("alive", true):
		d = minf(d, RM.model_to_unit_inches(m, str(info.surge_target), GameState.state))
Engine.set_meta("ork11e_goaded_d0", d)
Engine.set_meta("ork11e_goaded_target", str(info.surge_target))
return str(info.kind) == "surge" and int(info.roll) >= 1 and int(info.roll) <= 6 and float(info.max_inches) == float(info.roll) and str(info.surge_target) != "" and bool(info.reroll_available)

var RM = ResourceLoader.load("res://scripts/rules/ReactiveMove11e.gd")
var d := INF
for m in GameState.get_unit("U_BEAST_SNAGGA_BOYZ_A").models:
	if m.get("alive", true):
		d = minf(d, RM.model_to_unit_inches(m, str(Engine.get_meta("ork11e_goaded_target", "")), GameState.state))
return d < float(Engine.get_meta("ork11e_goaded_d0", 0.0))
